-- KO-352: Foundation 00 visual learning, applied checks, recall prompts, and mascot moments.
--
-- All numerical examples are illustrative or calculated teaching scenarios.
-- They are not market data, personal financial advice, or return promises.

BEGIN;

-- ---------------------------------------------------------------------------
-- 1. Reviewed primary sources
-- ---------------------------------------------------------------------------
INSERT INTO public.sources (
  source_code, title, local_title, source_tier, source_type, organization, url,
  language, last_checked_at, status, trust_notes, localization_notes, synopsis,
  synopsis_id, relevance_blurb, relevance_blurb_id
)
VALUES
  (
    'FZ-BI-INFLATION', 'Bank Indonesia inflation explainer', 'Penjelasan inflasi Bank Indonesia',
    1, 'website', 'Bank Indonesia',
    'https://www.bi.go.id/id/fungsi-utama/moneter/inflasi/Default.aspx', 'id', '2026-08-07', 'verified',
    'Primary Bank Indonesia explainer for the meaning, measurement, and economic effects of inflation.',
