INSERT INTO public.lesson_recall_questions (lesson_id, question_en, question_id, options_en, options_id, correct_option, explanation_en, explanation_id, is_active)
SELECT lesson.id, recalls.question_en, recalls.question_id, choices.options_en, choices.options_id,
  choices.correct_option, recalls.explanation_en, recalls.explanation_id, TRUE
FROM recalls JOIN public.lessons lesson ON lesson.slug = recalls.slug
CROSS JOIN LATERAL (
  SELECT
    jsonb_agg(jsonb_build_object('id', format('option_%s', en.ordinality), 'label', en.label) ORDER BY en.ordinality) AS options_en,
    jsonb_agg(jsonb_build_object('id', format('option_%s', id.ordinality), 'label', id.label) ORDER BY id.ordinality) AS options_id,
    format('option_%s', correct.ordinality) AS correct_option
  FROM jsonb_array_elements_text(recalls.options_en) WITH ORDINALITY AS en(label, ordinality)
  JOIN jsonb_array_elements_text(recalls.options_id) WITH ORDINALITY AS id(label, ordinality)
    ON id.ordinality = en.ordinality
  JOIN LATERAL (
    SELECT match.ordinality
    FROM jsonb_array_elements_text(recalls.options_en) WITH ORDINALITY AS match(label, ordinality)
    WHERE match.label = recalls.correct_option
    LIMIT 1
  ) AS correct ON TRUE
  GROUP BY correct.ordinality
) AS choices
WHERE lesson.is_published = TRUE
ON CONFLICT (lesson_id) DO UPDATE SET
  question_en = EXCLUDED.question_en, question_id = EXCLUDED.question_id, options_en = EXCLUDED.options_en,
  options_id = EXCLUDED.options_id, correct_option = EXCLUDED.correct_option,
  explanation_en = EXCLUDED.explanation_en, explanation_id = EXCLUDED.explanation_id,
  is_active = TRUE, updated_at = NOW();

COMMIT;
